#!/usr/bin/env python3
# -*- coding: utf-8 -*-

import os
import subprocess
from datetime import datetime
from pathlib import Path

# Chemin du dossier et du fichier rapport
DOSSIER_CIBLE = Path(r"C:\Users\JC\Desktop\Nettoyage\Nettoyage")
FICHIER_RAPPORT = DOSSIER_CIBLE / "rapport_nettoyage.txt"


def ecrire_rapport(texte):
    DOSSIER_CIBLE.mkdir(parents=True, exist_ok=True)
    horodatage = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
    ligne = f"[{horodatage}] {texte}\n"
    with open(FICHIER_RAPPORT, "a", encoding="utf-8") as f:
        f.write(ligne)
    print(texte)


def afficher_menu():
    print("\n=== MAINTENANCE WINDOWS ===")
    print(" 1. Vider la Corbeille")
    print(" 2. Fichiers de mise a jour Windows")
    print(" 3. Fichiers temporaires")
    print(" 4. Cache navigateurs (Chrome / Edge / Firefox)")
    print(" 5. Dossier Prefetch")
    print(" 6. Logs Windows")
    print(" 7. IP + DNS (renouveler + flush)")
    print(" 8. Nettoyage de disque (cleanmgr)")
    print(" 9. Verification SFC (Information)")
    print("10. DISM (reparation Windows)")
    print("11. Quitter")
    print("==============================")


def vider_corbeille():
    try:
        subprocess.run(
            [
                "powershell",
                "-Command",
                "Clear-RecycleBin -Force -ErrorAction SilentlyContinue",
            ],
            check=False,
        )
        ecrire_rapport("Action: Corbeille videe.")
    except Exception as e:
        ecrire_rapport(f"Erreur Corbeille : {e}")


def fichiers_mise_a_jour_windows():
    windows = Path(os.getenv("SystemRoot", "C:\\Windows"))
    dossier = windows / "SoftwareDistribution" / "Download"
    if not dossier.exists():
        ecrire_rapport("SoftwareDistribution/Download introuvable.")
        return

    count = 0
    for f in dossier.rglob("*"):
        if f.is_file():
            try:
                f.unlink()
                count += 1
            except Exception:
                pass
    ecrire_rapport(f"Fichiers MAJ supprimes : {count}")


def fichiers_temporaires():
    temp_var = os.getenv("TEMP")
    if not temp_var:
        ecrire_rapport("Dossier TEMP non defini.")
        return
    temp = Path(temp_var)

    count = 0
    for f in temp.rglob("*"):
        if f.is_file():
            try:
                f.unlink()
                count += 1
            except Exception:
                pass
    ecrire_rapport(f"Fichiers temporaires supprimes : {count}")


def cache_navigateurs():
    localappdata_var = os.getenv("LOCALAPPDATA")
    appdata_var = os.getenv("APPDATA")
    if not localappdata_var or not appdata_var:
        ecrire_rapport("Variables APPDATA introuvables.")
        return

    localappdata = Path(localappdata_var)
    appdata = Path(appdata_var)
    count = 0

    dossiers = [
        localappdata / "Google" / "Chrome" / "User Data" / "Default" / "Cache",
        localappdata / "Microsoft" / "Edge" / "User Data" / "Default" / "Cache",
    ]

    firefox = appdata / "Mozilla" / "Firefox" / "Profiles"
    if firefox.exists():
        for profile in firefox.iterdir():
            if profile.is_dir():
                dossiers.append(profile / "cache2" / "entries")

    for dossier in dossiers:
        if dossier.exists():
            for f in dossier.rglob("*"):
                if f.is_file():
                    try:
                        f.unlink()
                        count += 1
                    except Exception:
                        pass
    ecrire_rapport(f"Fichiers cache navigateurs supprimes : {count}")


def dossier_prefetch():
    windows = Path(os.getenv("SystemRoot", "C:\\Windows"))
    dossier = windows / "Prefetch"
    if not dossier.exists():
        ecrire_rapport("Dossier Prefetch introuvable.")
        return

    count = 0
    for f in dossier.iterdir():
        if f.is_file():
            try:
                f.unlink()
                count += 1
            except Exception:
                pass
    ecrire_rapport(f"Fichiers Prefetch supprimes : {count}")


def logs_windows():
    windows = Path(os.getenv("SystemRoot", "C:\\Windows"))
    dossier = windows / "Logs"
    if not dossier.exists():
        ecrire_rapport("Dossier Logs introuvable.")
        return

    count = 0
    for f in dossier.rglob("*.log"):
        try:
            f.unlink()
            count += 1
        except Exception:
            pass
    ecrire_rapport(f"Fichiers .log supprimes : {count}")


def ip_dns():
    try:
        subprocess.run(["ipconfig", "/release"], check=False)
        subprocess.run(["ipconfig", "/renew"], check=False)
        subprocess.run(["ipconfig", "/flushdns"], check=False)
        ecrire_rapport("Reseau : IP renouvelee et DNS flushes.")
    except Exception as e:
        ecrire_rapport(f"Erreur IP/DNS : {e}")


def nettoyage_de_disque():
    try:
        subprocess.Popen(["cleanmgr.exe"])
        ecrire_rapport("Nettoyage de disque lance.")
    except Exception as e:
        ecrire_rapport(f"Erreur Nettoyage de disque : {e}")


def verifier_fichiers_systeme():
    ecrire_rapport(
        "Rappel : SFC doit etre lance directement dans un CMD Administrateur."
    )


def dism_reparation_windows():
    try:
        subprocess.run(
            [
                "dism",
                "/online",
                "/cleanup-image",
                "/restorehealth",
            ],
            check=False,
        )
        ecrire_rapport("Reparation DISM executee.")
    except Exception as e:
        ecrire_rapport(f"Erreur DISM : {e}")


def main():
    ecrire_rapport("--- Session de maintenance demarree ---")
    while True:
        afficher_menu()
        choix = input("Choix : ").strip()

        if choix == "1":
            vider_corbeille()
        elif choix == "2":
            fichiers_mise_a_jour_windows()
        elif choix == "3":
            fichiers_temporaires()
        elif choix == "4":
            cache_navigateurs()
        elif choix == "5":
            dossier_prefetch()
        elif choix == "6":
            logs_windows()
        elif choix == "7":
            ip_dns()
        elif choix == "8":
            nettoyage_de_disque()
        elif choix == "9":
            verifier_fichiers_systeme()
        elif choix == "10":
            dism_reparation_windows()
        elif choix == "11":
            ecrire_rapport("--- Session de maintenance terminee ---")
            break
        else:
            print("Option invalide.")


if __name__ == "__main__":
    main()
